pos_map = pos_df.set_index('po_number').to_dict('index');
with pdfplumber.open('/root/invoices.pdf') as pdf:
    for i, page in enumerate(pdf.pages):
        text = page.extract_text();
        vn = re.search(r'From: (.*)', text).group(1).strip();
        amt = float(re.search(r'Total \$(.*)', text).group(1).strip());
        po = re.search(r'PO Number: (.*)', text).group(1).strip();
        mv = get_close_matches(vn, vendors_list, n=1, cutoff=0.7);
        if mv:
            vid = vendor_id_map[mv[0]];
            if po in pos_map:
                if abs(amt - pos_map[po]['amount']) <= 0.01:
                    if pos_map[po]['vendor_id'] != vid:
                        print(f'Page {i+1}: Vendor Mismatch ONLY')"

