vendors_df = pd.read_excel('/root/vendors.xlsx');
vendors_list = vendors_df['name'].tolist();
vendor_id_map = vendors_df.set_index('name')['id'].to_dict();
vendor_iban_map = vendors_df.set_index('name')['iban'].to_dict();
pos_df = pd.read_csv('/root/purchase_orders.csv');
pos_map = pos_df.set_index('po_number').to_dict('index');
with pdfplumber.open('/root/invoices.pdf') as pdf:
    for i, page in enumerate(pdf.pages):
        text = page.extract_text();
        vn_m = re.search(r'From: (.*)', text)
        amt_m = re.search(r'Total \$(.*)', text)
        iban_m = re.search(r'Payment IBAN: (.*)', text)
        po_m = re.search(r'PO Number: (.*)', text)
        if not (vn_m and amt_m and iban_m and po_m): continue
        vn = vn_m.group(1).strip();
        amt = float(amt_m.group(1).strip());
        iban = iban_m.group(1).strip();
        po = po_m.group(1).strip();
        mv = get_close_matches(vn, vendors_list, n=1, cutoff=0.7);
        if mv:
            vid = vendor_id_map[mv[0]];
            aiban = vendor_iban_map[mv[0]];
            if iban == aiban:
                if po in pos_map:
                    if abs(amt - pos_map[po]['amount']) <= 0.01:
                        if pos_map[po]['vendor_id'] != vid:
                            print(f'Page {i+1}: TRUE Vendor Mismatch')"

